{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C37"],
      "claim": "Umeclidinium, a quaternary ammonium antimuscarinic, has systemic bioavailability ≤12% after oral administration in healthy volunteers and negligible oral bioavailability; this is the closest structural and charge analogue to the query and directly supports low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "DX-9065a, a strongly basic amidine-containing small molecule, has human oral bioavailability of only 2–3%, attributed to its basic groups; this supports the poor absorption expected for the query's permanent quaternary ammonium charge.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Terfenadine has an absolute oral bioavailability of <2% in men, demonstrating that lipophilic molecules with extensive first-pass metabolism can have very low F; this supports low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Pravastatin has an absolute oral bioavailability of 18%, below the 20% threshold, due to incomplete intestinal absorption and hepatic first-pass extraction; this supports low F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a quaternary ammonium tropane ester (butylscopolamine-like cation). The closest analogue, umeclidinium, is also a quaternary ammonium antimuscarinic and has negligible/low oral bioavailability (≤12%). Additional strongly basic or high-first-pass compounds (DX-9065a, terfenadine, pravastatin) all show F <20%. The permanent positive charge and ester/epoxide liabilities make F ≥20% unlikely. Prediction: low.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for the query molecule itself.",
    "No data on specific transporter involvement (e.g., P-gp) or food effects for the query.",
    "No formulation-specific oral bioavailability data for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

